package ai.starlake.quack.edge.authz

import java.nio.charset.StandardCharsets
import java.util.Locale

/** Reads the classification tables bundled under `authz/`, generated by
  * scripts/dev/classify-qod-node.py: one row per line, tab-separated cells, `#` lines and blank
  * lines skipped.
  */
private[authz] object ClassificationTables:

  /** The bundled resource's text; throws IllegalStateException when the jar lacks it. */
  def read(resource: String): String =
    Option(getClass.getClassLoader.getResourceAsStream(resource)) match
      case Some(in) =>
        try new String(in.readAllBytes(), StandardCharsets.UTF_8)
        finally in.close()
      case None => throw new IllegalStateException(s"the bundled resource $resource is missing")

  /** The data rows of `text` with their line numbers, each split into exactly `columns` non-empty
    * lowercase cells. Throws IllegalArgumentException naming the first line that is not.
    */
  def rows(text: String, columns: Int): List[(Int, Vector[String])] =
    text.linesIterator.zipWithIndex
      .filter { case (line, _) => line.nonEmpty && !line.startsWith("#") }
      .map { case (line, i) =>
        val cells = line.split("\t", -1).toVector
        if cells.length != columns || cells
            .exists(c => c.isEmpty || c != c.toLowerCase(Locale.ROOT))
        then
          throw new IllegalArgumentException(
            s"line ${i + 1}: expected $columns non-empty lowercase tab-separated cells"
          )
        else (i + 1, cells)
      }
      .toList
